const KEY_LED_COUNT = indexes.length;
const SIDE_LED_INDEX = vKeyNames.length - 1;

let lastSideSignature = "";
let lastKeyboardSignature = "";

const SIDE_MODE_IDS = {
    "Light Flow": 0x01,
    "Static": 0x02,
    "Dynamic Breathing": 0x03,
    "Spectrum Cycle": 0x04
};

const SIDE_MODE_FLAGS = {
    0x01: 0x01,
    0x02: 0x00,
    0x03: 0x00,
    0x04: 0x01,
    0x05: 0x01
};

export function Initialize() {
    const modePacket = new Array(65).fill(0);
    modePacket[0] = 0x00; 
    modePacket[1] = 0xaa;
    modePacket[2] = 0x23;
    modePacket[3] = 0x10;
    modePacket[4] = 0x00;
    modePacket[5] = 0x00;
    modePacket[6] = 0x00;
    modePacket[7] = 0x01;
    modePacket[8] = 0x00;
    // 0x14 is the keyboard's custom/software lighting mode.
    modePacket[9] = 0x14;
    modePacket[10] = 0xa3;
    modePacket[11] = 0x2e;
    modePacket[12] = 0xff;
    modePacket[13] = 0xff;
    modePacket[18] = 0x06;
    modePacket[19] = 0x04;
    modePacket[23] = 0xaa;
    modePacket[24] = 0x55;
    
    device.write(modePacket, 65);
    device.pause(50);
    lastSideSignature = "";
    lastKeyboardSignature = "";
    updateSideLighting();
}


export function LedNames() { return vKeyNames; }
export function LedPositions() { return vKeyPositions; }

export function Render() {
    sendColors();
    updateSideLighting();
}
export function Shutdown() {
    sendColors(true, true);
    sendSideLighting(0x05, [0, 0, 0], 1, 1);
    lastKeyboardSignature = "";
    lastSideSignature = "";
}

function sendColors(shutdown = false, force = false) {
    // The official Aula capture waits about 14-15 ms for the keyboard's echo
    // after every AA 24 packet. Never allow a shorter software pacing delay.
    const delayMs = getInterPacketDelay();
    const rgbData = grabColors(shutdown);
    const keyboardSignature = rgbData.slice(0, KEY_LED_COUNT * 3).join(",");

    if (!force && keyboardSignature === lastKeyboardSignature) return;

    // The AULA protocol always transfers a 128-entry key table. Each entry is
    // [hardware key ID, red, green, blue]. LEDs not exposed by this layout stay
    // black. The indexes array maps SignalRGB LED order to hardware key IDs.
    const sendData = new Array(512).fill(0);
    for (let keyId = 0; keyId < 128; keyId++) {
        sendData[keyId * 4] = keyId;
    }

    for (let led = 0; led < KEY_LED_COUNT; led++) {
        const target = indexes[led] * 4;
        sendData[target + 1] = rgbData[led * 3];
        sendData[target + 2] = rgbData[led * 3 + 1];
        sendData[target + 3] = rgbData[led * 3 + 2];
    }

    // Nine 0x38 packets transfer the first 504 bytes (IDs 0x00-0x7d).
    for (let segment = 0; segment < 9; segment++) {
        const offset = segment * 56;
        const packet = new Array(65).fill(0);
        packet[0] = 0x00; // HID report ID / zero padding
        packet[1] = 0xaa;
        packet[2] = 0x24; // write custom RGB table
        packet[3] = 0x38;
        packet[4] = offset & 0xff;
        packet[5] = (offset >> 8) & 0xff;

        for (let j = 0; j < 56; j++) {
            packet[9 + j] = sendData[offset + j];
        }

        device.write(packet, 65);
        device.pause(delayMs);
    }

    // Final packet transfers IDs 0x7e-0x7f and commits/applies the table.
    const finalPacket = new Array(65).fill(0);
    finalPacket[0] = 0x00;
    finalPacket[1] = 0xaa;
    finalPacket[2] = 0x24;
    finalPacket[3] = 0x08;
    finalPacket[4] = 0xf8;
    finalPacket[5] = 0x01;
    finalPacket[6] = 0x00;
    finalPacket[7] = 0x01;
    finalPacket[8] = 0x00;
    for (let j = 0; j < 8; j++) {
        finalPacket[9 + j] = sendData[504 + j];
    }
    device.write(finalPacket, 65);
    device.pause(delayMs);
    lastKeyboardSignature = keyboardSignature;
}



function grabColors(shutdown = false) {
    const rgbData = new Array(vKeyNames.length * 3).fill(0);

    const overrideColor = shutdown
        ? hexToRgb(shutdownColor)
        : LightingMode === "Forced" ? hexToRgb(forcedColor) : null;

    for (let led = 0; led < vKeyPositions.length; led++) {
        const position = vKeyPositions[led];
        const color = overrideColor || device.color(position[0], position[1]) || [0, 0, 0];
        const offset = led * 3;
        rgbData[offset] = color[0] || 0;
        rgbData[offset + 1] = color[1] || 0;
        rgbData[offset + 2] = color[2] || 0;
    }

    return rgbData;
}




function hexToRgb(hex) {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    if (!result) return [0, 0, 0];
    return [
        parseInt(result[1], 16),
        parseInt(result[2], 16),
        parseInt(result[3], 16)
    ];
}

function clampSideLevel(value) {
    return Math.max(1, Math.min(6, Math.floor(Number(value) || 1)));
}

function getInterPacketDelay() {
    const parsedDelay = parseInt(String(InterPacketDelayMs), 10);
    return Math.max(15, Math.min(30, parsedDelay || 18));
}

function sendSideLighting(mode, color, speed, brightness) {
    const packet = new Array(65).fill(0);
    packet[0] = 0x00; // HID report ID / zero padding
    packet[1] = 0xaa;
    packet[2] = 0x2b;
    packet[3] = 0x18;
    packet[7] = 0x01;
    packet[9] = mode;
    packet[10] = color[0];
    packet[11] = color[1];
    packet[12] = color[2];
    packet[17] = SIDE_MODE_FLAGS[mode];
    // Capture order is brightness first, then speed.
    packet[18] = brightness;
    packet[19] = speed;
    device.write(packet, 65);
    device.pause(getInterPacketDelay());
}

function updateSideLighting() {
    if (SideControl === "Leave Unchanged") {
        lastSideSignature = "leave";
        return;
    }

    const speed = clampSideLevel(SideSpeed);
    const brightness = clampSideLevel(SideBrightness);
    let mode;
    let color;

    if (SideControl === "Off") {
        mode = 0x05;
        color = hexToRgb(SideColor);
    } else if (SideControl === "Canvas Static") {
        mode = 0x02;
        const sidePosition = vKeyPositions[SIDE_LED_INDEX];
        color = device.color(sidePosition[0], sidePosition[1]) || [0, 0, 0];
    } else {
        mode = SIDE_MODE_IDS[SideMode] || 0x02;
        color = hexToRgb(SideColor);
    }

    color = [color[0] || 0, color[1] || 0, color[2] || 0];
    const signature = [SideControl, mode, color[0], color[1], color[2], speed, brightness].join(":");
    if (signature === lastSideSignature) return;

    sendSideLighting(mode, color, speed, brightness);
    lastSideSignature = signature;
}

export function Validate(endpoint) {
	return endpoint.interface === 2 && endpoint.usage_page === 0xFF68;
}

export function ImageUrl() { return "data:image/png;base64,"; }
